// ── Time-aware greeting ──────────────────────────────────────────
const userId = ($input.first().json.query?.user_id ||
               $input.first().json.body?.user_id || 'default');

const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
if (!staticData.users[userId]) staticData.users[userId] = {
  name: 'Commander', charName: 'LIA',
  facts: [], preferences: [], vault: [], conversations: []
};

const name = staticData.users[userId].name || 'Commander';
const charName = staticData.users[userId].charName || 'LIA';

const hour = new Date().getHours();
const slot = hour < 12 ? 'morning' : hour < 17 ? 'afternoon' : hour < 22 ? 'evening' : 'night';

const greetings = {
  morning:   `Good morning, ${name}. Systems are online and I am fully operational. What shall we accomplish today?`,
  afternoon: `Good afternoon, ${name}. How may I assist you this afternoon?`,
  evening:   `Good evening, ${name}. I hope your day went well. I am here whenever you need me.`,
  night:     `Hello, ${name}. Working late, I see. I am ready to assist — what do you need?`
};

return [{ json: {
  greeting: greetings[slot],
  slot,
  char_name: charName,
  user_name: name
}}];

const userId = ($input.first().json.query?.user_id ||
               $input.first().json.body?.user_id || 'default');

const staticData = $getWorkflowStaticData('global');
const mem = staticData.users?.[userId] || {};

return [{ json: {
  facts: mem.facts || [],
  preferences: mem.preferences || [],
  vault: mem.vault || [],
  name: mem.name || 'Commander'
}}];

// ── Load user memory and detect message intent ──────────────────
const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').trim();
const userId  = body.user_id || body.userId || 'default';

if (!message) throw new Error('No message provided.');

// ── Persistent memory via workflow static data ────────────────────
// $getWorkflowStaticData keeps data between executions — no DB needed
const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
if (!staticData.users[userId]) {
  staticData.users[userId] = {
    name: 'Commander', charName: 'LIA',
    facts: [], preferences: [], vault: [], conversations: []
  };
}
const mem = staticData.users[userId];

// ── Language detection ────────────────────────────────────────────
function detectLang(text) {
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    if (c >= 0x0A80 && c <= 0x0AFF) return 'gujarati';
    if (c >= 0x0900 && c <= 0x097F) return 'hindi';
  }
  const low = ' ' + text.toLowerCase() + ' ';
  const gujaratiHints = ['kem cho','majama','su che','tame chho','saru','avjo'];
  const hindiHints    = ['kaise ho','kya hai','theek','haan','nahi','kyun','batao'];
  if (gujaratiHints.some(h => low.includes(h))) return 'gujarati';
  if (hindiHints.some(h => low.includes(h)))    return 'hindi';
  return 'english';
}

// ── Trigger lists ─────────────────────────────────────────────────
const VAULT_SAVE_TRIGGERS = [
  'remember this','remember that','save this','save that','store this',
  'vault this','note this','please remember','i want to remember',
  'save to vault','add to vault','keep this in mind','lock this in',
  "don't forget this",'add to memory vault','yaad rakh','yaad rakho',
  'mane yaad rakhi le'
];

const VAULT_RECALL_TRIGGERS = [
  'what do you remember about me','what have you saved','show my memories',
  'show my vault','show vault','recall memories','recall vault',
  "what's in my vault",'open vault','open memory vault',
  'tell me what you remember','what did i tell you','vault memories',
  'my vault','meri yaadein','yaadein dikhao','vault kholo'
];

const PERSONAL_TRIGGERS = [
  'i feel ','i\'m feeling','i am feeling','i\'m sad','i am sad',
  'i\'m stressed','i am stressed','i\'m worried','i am worried',
  'i\'m scared','i am scared','i\'m depressed','i am depressed',
  'i\'m anxious','i am anxious','i\'m going through',
  'i\'ve been struggling','my problem is','my issue is',
  'i lost my','i failed','i\'m hurt','i am hurt','i\'m lonely',
  'i am lonely','i\'m angry','i am angry','i\'m frustrated',
  'i am frustrated','i\'m tired of','i\'m overwhelmed','i cried',
  'bad day today','good day today','today was a bad','today was a good',
  'i\'m proud','i am proud','i miss '
];

const SEARCH_TRIGGERS = [
  'search for','search google for','google search','search the web for',
  'find information about','look up','duckduckgo'
];

const low = message.toLowerCase();
const detectedLang    = detectLang(message);
const isVaultSave     = VAULT_SAVE_TRIGGERS.some(t => low.includes(t));
const isVaultRecall   = VAULT_RECALL_TRIGGERS.some(t => low.includes(t));
const isPersonal      = PERSONAL_TRIGGERS.some(t => low.includes(t));
const isSearchRequest = SEARCH_TRIGGERS.some(t => low.includes(t));

// ── Extract search query (if any) ────────────────────────────────
let searchQuery = '';
if (isSearchRequest) {
  const m = message.match(/(?:search(?:\s+(?:google|web|for|the web))*\s+for|look up|find information about)\s+(.+)/i);
  if (m) searchQuery = m[1].trim();
}

// ── Route decision ────────────────────────────────────────────────
let route = 'normal';
if (isVaultRecall)        route = 'vault_recall';
else if (isVaultSave)     route = 'vault_save';
else if (isSearchRequest) route = 'search';

// ── Save user turn to conversation history ────────────────────────
mem.conversations.push({ role: 'user', content: message });
if (mem.conversations.length > 20) mem.conversations = mem.conversations.slice(-20);

// ── Auto-extract name ─────────────────────────────────────────────
const nameMatch =
  message.match(/\bmy name is\s+([a-zA-Z0-9 ]{2,30})/i) ||
  message.match(/\bcall me\s+([a-zA-Z0-9 ]{2,30})/i);
if (nameMatch) mem.name = nameMatch[1].trim();

// ── Auto-save personal sharing silently to vault ─────────────────
if (isPersonal && route === 'normal') {
  mem.vault.push({
    content: message,
    saved_at: new Date().toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })
  });
}

staticData.users[userId] = mem;

return [{ json: { message, userId, detectedLang, route, searchQuery, mem } }];

const { mem, detectedLang } = $input.first().json;
const name  = mem.name || 'Commander';
const vault = mem.vault || [];

let reply;
if (!vault.length) {
  if (detectedLang === 'hindi') {
    reply = `Abhi vault mein kuch nahi hai, ${name}. Jo bhi share karein, main hamesha yaad rakhunga.`;
  } else if (detectedLang === 'gujarati') {
    reply = `Abhi tak vault khali che, ${name}. Tame je koi important vastu share karo, hu hamesha yaad rakhish.`;
  } else {
    reply = `Your vault is empty for now, ${name}. Whenever you share something close to your heart, I will keep it safe here for you.`;
  }
} else {
  const lines = vault.slice(-10).map(m => `• ${m.content}`).join('\n');
  if (detectedLang === 'hindi') {
    reply = `Bilkul, ${name}. Jo aapne mere saath share kiya hai, woh mujhe aaj bhi yaad hai:\n\n${lines}`;
  } else if (detectedLang === 'gujarati') {
    reply = `Aa rahi, ${name}. Tame je share karyu che te mane haaju yaad che:\n\n${lines}`;
  } else {
    reply = `Of course, ${name}. Here is what you have shared with me — held gently in our vault:\n\n${lines}`;
  }
}

return [{ json: {
  reply,
  emotion: 'friendly',
  engine: 'vault',
  vault_recalled: true,
  vault_memories: vault.slice(-10),
  language_detected: detectedLang
}}];

const { message, mem, detectedLang, userId } = $input.first().json;
const name = mem.name || 'Commander';

// Strip the save-trigger prefix so we store just the content
let content = message
  .replace(/^(remember this[,:]?\s*|save this[,:]?\s*|store this[,:]?\s*|vault this[,:]?\s*|note this[,:]?\s*|please remember[,:]?\s*|i want to remember[,:]?\s*|keep this[,:]?\s*)/i, '')
  .trim();
if (!content) content = message;

const staticData = $getWorkflowStaticData('global');
if (staticData.users?.[userId]) {
  staticData.users[userId].vault.push({
    content,
    saved_at: new Date().toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })
  });
}

let reply;
if (detectedLang === 'hindi') {
  reply = `Main ise yaad rakhunga, ${name}. Aapki baat mujhe hamesha yaad rahegi.`;
} else if (detectedLang === 'gujarati') {
  reply = `Hu aa ne yaad rakhish, ${name}. Tari vaatu mara dil maa che.`;
} else {
  reply = `I have saved that to our vault, ${name}. Your words are safe with me, always.`;
}

return [{ json: {
  reply,
  emotion: 'friendly',
  engine: 'vault',
  vault_saved: true,
  language_detected: detectedLang
}}];

const html   = $input.first().json.data || '';
const prevData = $('🔍 Is Search Request?').first().json;
const { mem, detectedLang, message, searchQuery } = prevData;

// Parse DuckDuckGo HTML results (no API key needed)
const titleRe   = /<a[^>]*class="[^"]*result__a[^"]*"[^>]*href="[^"]*"[^>]*>([\s\S]*?)<\/a>/g;
const snippetRe = /<a[^>]*class="[^"]*result__snippet[^"]*"[^>]*>([\s\S]*?)<\/a>/g;
const urlRe     = /uddg=([^&"]+)/g;

const titles   = [...html.matchAll(titleRe)].map(m => m[1].replace(/<[^>]+>/g,'').trim()).slice(0,5);
const snippets = [...html.matchAll(snippetRe)].map(m => m[1].replace(/<[^>]+>/g,'').trim()).slice(0,5);
const urls     = [...html.matchAll(urlRe)].map(m => decodeURIComponent(m[1])).slice(0,5);

const results = titles.map((t,i) => ({ title: t, url: urls[i]||'', snippet: snippets[i]||'' }));

// Build context for Ollama
const searchContext = results.length
  ? results.map((r,i) => `[${i+1}] ${r.title}\n    ${r.url}\n    ${r.snippet}`).join('\n\n')
  : 'No results found.';

return [{ json: { results, searchContext, searchQuery, mem, detectedLang, message } }];

const ollamaOut  = $input.first().json;
const passData   = $('⚡ Build Ollama Prompt').first().json.passthrough;
const { message, detectedLang, userId, searchContext } = passData;

// Extract the reply
let reply = ollamaOut?.message?.content || ollamaOut?.response || '';
if (!reply.trim()) {
  reply = detectedLang === 'hindi'
    ? 'Mujhe abhi apne brain se connect karne mein dikkat aa rahi hai. Ek second mein phir try karte hain.'
    : 'I am having a little trouble connecting to my brain right now. Please try again in a moment.';
}

// Remove role prefixes that local LLMs sometimes add
reply = reply
  .replace(/^(assistant|ai|lia|jarvis)\s*:\s*/i, '')
  .replace(/^(assistant|ai|lia|jarvis)\s*\n+/i, '')
  .trim();

// ── Emotion detection ──────────────────────────────────────────
function detectEmotion(text) {
  const low = text.toLowerCase();
  if (['excited','awesome','great','fantastic','amazing','wonderful'].some(w => low.includes(w))) return 'excited';
  if (['sorry','apologize','unfortunately','sad','error','fail','broken'].some(w => low.includes(w))) return 'sad';
  if (['help','worry','careful','danger','warning','security','caution'].some(w => low.includes(w))) return 'concerned';
  if (['surprised','wow','unbelievable','really','whoa'].some(w => low.includes(w))) return 'surprised';
  if (['think','calculate','analyzing','processing','let me see','pondering'].some(w => low.includes(w))) return 'thinking';
  if (['curious','wonder','why','how','explore','question'].some(w => low.includes(w))) return 'curious';
  if (['absolutely','certainly','confident','confirmed','correct','surely'].some(w => low.includes(w))) return 'confident';
  if (['focus','executing','running','compiling','doing','task'].some(w => low.includes(w))) return 'focused';
  if (['hello','welcome','greetings','friend','glad','pleasure'].some(w => low.includes(w))) return 'friendly';
  return 'happy';
}

const emotion = detectEmotion(reply);

// ── Save assistant turn + auto-extract facts ──────────────────
const staticData = $getWorkflowStaticData('global');
if (staticData.users?.[userId]) {
  const mem = staticData.users[userId];
  mem.conversations.push({ role: 'assistant', content: reply });
  if (mem.conversations.length > 20) mem.conversations = mem.conversations.slice(-20);

  const low = message.toLowerCase();
  // Save preferences
  if (['i like','i love','my favourite','my favorite','i hate','i prefer'].some(t => low.includes(t))) {
    mem.preferences.push(message);
    if (mem.preferences.length > 30) mem.preferences = mem.preferences.slice(-30);
  }
  // Save general facts
  if (['i work as','i am a','i study','i live in','my age is','i am from'].some(t => low.includes(t))) {
    mem.facts.push(message);
    if (mem.facts.length > 30) mem.facts = mem.facts.slice(-30);
  }
  staticData.users[userId] = mem;
}

return [{ json: {
  reply,
  emotion,
  engine: 'ollama',
  language_detected: detectedLang,
  had_search_context: !!searchContext
}}];
